function statusLabel(status: string) { return ({ pending: 'Pendiente', confirmed: 'Confirmada', completed: 'Completada', cancelled: 'Cancelada' } as Record<string, string>)[status] || status; }
function pickBrowserFile(): Promise<SelectedRecordFile | null> { return new Promise(resolve => { const input = document.createElement('input'); input.type = 'file'; input.accept = 'application/pdf,image/jpeg,image/png'; input.onchange = () => resolve(input.files?.[0] || null); input.addEventListener('cancel', () => resolve(null), { once: true }); input.click(); }); }
function formatBytes(value: number) { return value < 1024 * 1024 ? `${Math.max(1, Math.round(value / 1024))} KB` : `${(value / 1024 / 1024).toFixed(1)} MB`; }
function localDateTimeNow() { return new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 16); }
function Card({ palette, children }: { palette: (typeof Colors)[keyof typeof Colors]; children: React.ReactNode }) { return <View style={[styles.card, { backgroundColor: palette.backgroundElement, borderColor: palette.line }]}>{children}</View>; }
function SectionTitle({ title, palette }: { title: string; palette: (typeof Colors)[keyof typeof Colors] }) { return <Text style={[styles.sectionTitle, { color: palette.text }]}>{title}</Text>; }
function Action({ title, onPress, palette, disabled = false }: { title: string; onPress: () => void; palette: (typeof Colors)[keyof typeof Colors]; disabled?: boolean }) { return <Pressable accessibilityRole="button" disabled={disabled} onPress={onPress} style={[styles.action, { backgroundColor: palette.primarySoft, opacity: disabled ? 0.55 : 1 }]}><Text style={{ color: palette.primary, fontSize: 13, fontWeight: '700' }}>{title}</Text></Pressable>; }
function Field({ label, value, onChangeText, keyboardType, palette }: { label: string; value: string; onChangeText: (value: string) => void; keyboardType?: 'email-address' | 'phone-pad' | 'numeric'; palette: (typeof Colors)[keyof typeof Colors] }) { return <View style={styles.field}><Text style={[styles.meta, { color: palette.text }]}>{label}</Text><TextInput accessibilityLabel={label} value={value} onChangeText={onChangeText} keyboardType={keyboardType} autoCapitalize={keyboardType === 'email-address' ? 'none' : 'sentences'} placeholderTextColor={palette.textSecondary} style={[styles.input, { color: palette.text, backgroundColor: palette.background, borderColor: palette.line }]} /></View>; }
function Choice({ title, value, items, onChange, palette, allowNone = true }: { title: string; value: string; items: { id: string; name: string }[]; onChange: (value: string) => void; palette: (typeof Colors)[keyof typeof Colors]; allowNone?: boolean }) { return <View style={styles.field}><Text style={[styles.meta, { color: palette.text }]}>{title}</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.choices}>{allowNone ? <Pressable onPress={() => onChange('')} style={[styles.chip, { backgroundColor: !value ? palette.primarySoft : palette.background, borderColor: !value ? palette.primary : palette.line }]}><Text style={{ color: !value ? palette.primary : palette.textSecondary }}>Sin asignar</Text></Pressable> : null}{items.map(item => <Pressable key={item.id} onPress={() => onChange(item.id)} style={[styles.chip, { backgroundColor: value === item.id ? palette.primarySoft : palette.background, borderColor: value === item.id ? palette.primary : palette.line }]}><Text numberOfLines={1} style={{ color: value === item.id ? palette.primary : palette.text }}>{item.name}</Text></Pressable>)}</ScrollView></View>; }
function MultiField({ label, value, onChangeText, palette }: { label: string; value: string; onChangeText: (value: string) => void; palette: (typeof Colors)[keyof typeof Colors] }) { return <View style={styles.field}><Text style={[styles.meta, { color: palette.text }]}>{label}</Text><TextInput accessibilityLabel={label} value={value} onChangeText={onChangeText} multiline textAlignVertical="top" placeholderTextColor={palette.textSecondary} style={[styles.input, styles.textarea, { color: palette.text, backgroundColor: palette.background, borderColor: palette.line }]} /></View>; }
